from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import psycopg2

app = FastAPI()
conn = psycopg2.connect("dbname=taskhive user=postgres password=yourpassword")
cur = conn.cursor()

class Task(BaseModel):
    id: int
    title: str
    priority: str

@app.post("/tasks/")
def create_task(task: Task):
    cur.execute("INSERT INTO tasks (title, priority) VALUES (%s, %s) RETURNING id", (task.title, task.priority))
    conn.commit()
    task_id = cur.fetchone()[0]
    return {"id": task_id, "title": task.title, "priority": task.priority}

@app.get("/tasks/")
def list_tasks():
    cur.execute("SELECT id, title, priority FROM tasks")
    tasks = cur.fetchall()
    return [{"id": task[0], "title": task[1], "priority": task[2]} for task in tasks]

@app.put("/tasks/{task_id}/complete")
def complete_task(task_id: int):
    cur.execute("UPDATE tasks SET completed=True WHERE id=%s", (task_id,))
    conn.commit()
    if cur.rowcount == 0:
        raise HTTPException(status_code=404, detail="Task not found")
