import pika
from google.protobuf.json_format import Parse

class GaleGuardWorker:
    def __init__(self):
        self.connection = pika.BlockingConnection(pika.ConnectionParameters('localhost'))
        self.channel = self.connection.channel()
        self.channel.queue_declare(queue='weather_readings')

    def start_listening(self):
        def callback(ch, method, properties, body):
            reading = Parse(body, WeatherReading())
            if reading.wind_speed > 60:
                self.send_alert(reading.location)

        self.channel.basic_consume(queue='weather_readings', on_message_callback=callback, auto_ack=True)
        self.channel.start_consuming()

    def send_alert(self, location):
        print(f"Alert: Wind speed above 60 km/h detected in {location}.")

class WeatherReading:
    def __init__(self, wind_speed=0, location="Unknown"):
        self.wind_speed = wind_speed
        self.location = location

if __name__ == "__main__":
    worker = GaleGuardWorker()
    worker.start_listening()
