from fastapi import FastAPI
from kafka import KafkaConsumer
import json

app = FastAPI()

class StormWatch:
    def __init__(self):
        self.consumer = KafkaConsumer('weather_readings', bootstrap_servers='localhost:9092', auto_offset_reset='earliest')
        self.threshold = 60  # km/h

    def process_reading(self, reading):
        if reading['wind_speed'] > self.threshold:
            print(f"Alert: Wind speed of {reading['wind_speed']} km/h exceeds the threshold of {self.threshold} km/h.")

storm_watch = StormWatch()

@app.post("/start")
async def start():
    for msg in storm_watch.consumer:
        storm_watch.process_reading(json.loads(msg.value))
