from pymongo import MongoClient
from bson.objectid import ObjectId

app = Flask(__name__)
client = MongoClient('mongodb://localhost:27017/')
db = client['TaskHiveDB']
tasks_col = db['tasks']

@app.route('/tasks', methods=['POST'])
def create_task():
    data = request.get_json()
    task_id = tasks_col.insert_one(data).inserted_id
    return jsonify(str(task_id)), 201

@app.route('/tasks', methods=['GET'])
def list_tasks():
    tasks = tasks_col.find()
    task_list = [task for task in tasks]
    return jsonify(task_list)

@app.route('/tasks/<task_id>', methods=['PUT'])
def complete_task(task_id):
    if tasks_col.find_one({"_id": ObjectId(task_id)}):
        tasks_col.update_one({"_id": ObjectId(task_id)}, {"$set": {"status": "completed"}})
        return jsonify({"message": "Task marked as completed"}), 200
    return jsonify({"error": "Task not found"}), 404

if __name__ == '__main__':
    app.run(debug=True)
```

