from flask import Flask, request
from flask_pymongo import PyMongo
from bson.objectid import ObjectId

app = Flask(__name__)
app.config["MONGO_URI"] = "mongodb://localhost:27017/TaskHive"
mongo = PyMongo(app)

@app.route('/tasks', methods=['POST'])
def create_task():
    title = request.json.get('title')
    priority = request.json.get('priority', 'medium')
    task_id = mongo.db.tasks.insert_one({'title': title, 'priority': priority}).inserted_id
    return {'task_id': str(task_id)}, 201

@app.route('/tasks', methods=['GET'])
def list_tasks():
    tasks = mongo.db.tasks.find().sort('priority', 1).sort('title', 1)
    return {'tasks': [task for task in tasks]}

@app.route('/tasks/<task_id>/complete', methods=['PUT'])
def complete_task(task_id):
    result = mongo.db.tasks.update_one({'_id': ObjectId(task_id)}, {'$set': {'completed': True}})
    if result.matched_count == 0:
        return {'error': 'Task not found'}, 404
    return {'message': 'Task completed'}

