import pika
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class Config(BaseModel):
    threshold: int = 80

config = Config()

class Message(BaseModel):
    wind_speed: float

def connect_to_rabbitmq():
    connection = pika.BlockingConnection(pika.ConnectionParameters('localhost'))
    channel = connection.channel()
    channel.queue_declare(queue='weather_queue')
    return channel

@app.post("/config")
def update_config(threshold: int):
    global config
    if threshold < 0:
        raise HTTPException(status_code=400, detail="Threshold must be non-negative")
    config = Config(threshold=threshold)
    return {"threshold": config.threshold}

@app.get("/status")
def check_status():
    return {"status": "Alert" if config.threshold < 80 else "No Alert"}

@app.post("/alert")
def trigger_alert():
    return {"status": "Alert triggered"}

@app.post("/weather")
async def process_weather_message(message: Message):
    if message.wind_speed > config.threshold:
        channel = connect_to_rabbitmq()
        channel.basic_publish(exchange='', routing_key='weather_queue', body=str(message.wind_speed))
        return {"message": "Alert sent"}
    return {"message": "No alert"}

# Entry point
if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
